        if not cnf:
            return True
        literal = next((l for l in range(-n, n+1) if l not in assignment and -l not in assignment), None)
        if literal is None:
            return False

        def propagate(lit):
            new_cnf = []
            for clause in cnf:
                if lit in clause:
                    continue
                elif -lit in clause:
                    clause.remove(-lit)
                    if not clause:
                        return False
                else:
                    new_cnf.append(clause)
            return new_cnf

        def backtrack(lit):
            assignment.pop(lit, None)

        if propagate(literal):
            if dpll(cnf, assignment | {literal: True}):
                return True
            backtrack(literal)
        if propagate(-literal):
            if dpll(cnf, assignment | {-literal: True}):
                return True
            backtrack(-literal)
        return False

    def arithmetic_hierarchy_depth(cnf):
        depth = 0
        for clause in cnf:
